$names=@('cdb','ntsd','windbg','windbgx','kd','procdump','procexp','procexp64','lldb','gdb','wpr','wpa','resmon','taskmgr'); $found=@(Get-Command $names -ErrorAction SilentlyContinue | Select-Object Name,Source); $roots=@('C:/Program Files','C:/Program Files (x86)',"$env:LOCALAPPDATA/Programs","$env:LOCALAPPDATA/Microsoft/WindowsApps","$env:USERPROFILE/.vscode/extensions",'C:/Tools','C:/Sysinternals'); $scans=@(); foreach($p in $roots){if(Test-Path -LiteralPath $p){$matches=@(rg --files --hidden --no-ignore $p 2>$null | Select-String -Pattern '(?i)(^|[/\\])(cdb|ntsd|windbgx?|kd|procexp(64|64a)?|procdump(64)?|wpa|lldb|gdb)\.exe$' | ForEach-Object {$_.Line});$scans+=@{root=$p;matches=$matches;note='Unreadable entries omitted; not an exhaustive machine inventory'}}else{$scans+=@{root=$p;exists=$false}}}; @{commands=$found;scans=$scans;windbg_packages=@(Get-AppxPackage '*WinDbg*' -ErrorAction SilentlyContinue | Select-Object Name,InstallLocation)} | ConvertTo-Json -Depth 5
